    while (b) {
        uint32_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static void append_group(uint32_t *g, uint32_t *end, uint8_t *count,
                         uint32_t value, uint32_t endpoint) {
    if (*count && g[*count - 1] == value) {
        end[*count - 1] = endpoint;
    } else if (*count < MAX_GROUPS) {
        g[*count] = value;
        end[*count] = endpoint;
        ++(*count);
    }
}

static void make_leaf(Node *node, uint32_t value) {
    memset(node, 0, sizeof(*node));
    node->len = 1;
    node->np = node->ns = 1;
    node->pg[0] = node->sg[0] = value;
    node->pe[0] = node->se[0] = 1;
    node->good = value > 1;
}

