        make_leaf(temporary, values[position]);
    } else {
        memset(temporary, 0, sizeof(*temporary));
    }
    return temporary;
}

static void merge_nodes(Node *out, const Node *a, const Node *b) {
    memset(out, 0, sizeof(*out));
    out->len = a->len + b->len;

    uint32_t full_a = a->np ? a->pg[a->np - 1] : 0;
    uint32_t full_b = b->np ? b->pg[b->np - 1] : 0;

    for (int i = 0; i < a->np; ++i)
        append_group(out->pg, out->pe, &out->np, a->pg[i], a->pe[i]);

    for (int i = 0; i < b->np; ++i) {
        uint32_t value = gcd_u32(full_a, b->pg[i]);
        append_group(out->pg, out->pe, &out->np, value,
                     (uint32_t)a->len + b->pe[i]);
    }

    for (int i = 0; i < b->ns; ++i)
