static int gcd_int(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static void append_group(int *gcds, int *counts, int *size, int value, int count) {
    if (*size > 0 && gcds[*size - 1] == value) {
        counts[*size - 1] += count;
    } else {
        gcds[*size] = value;
        counts[*size] = count;
        ++(*size);
    }
}

static void merge_nodes(const Node *left, const Node *right, Node *out) {
    out->len = left->len + right->len;
    out->gcd_all = gcd_int(left->gcd_all, right->gcd_all);
    out->answer = left->answer + right->answer;

    if (gcd_int(left->gcd_all, right->gcd_all) > 1) {
        out->answer += (long long)left->len * right->len;
    } else {
        for (int i = 0; i < left->suffix_count; ++i) {
            for (int j = 0; j < right->prefix_count; ++j) {
                if (gcd_int(left->suffix_gcd[i], right->prefix_gcd[j]) > 1) {
                    out->answer += (long long)left->suffix_len[i] * right->prefix_len[j];
                }
            }
        }
    }

    out->prefix_count = 0;
    for (int i = 0; i < left->prefix_count; ++i) {
        append_group(out->prefix_gcd, out->prefix_len, &out->prefix_count,
                     left->prefix_gcd[i], left->prefix_len[i]);
    }
    for (int i = 0; i < right->prefix_count; ++i) {
        append_group(out->prefix_gcd, out->prefix_len, &out->prefix_count,
                     gcd_int(left->gcd_all, right->prefix_gcd[i]),
                     right->prefix_len[i]);
    }

    out->suffix_count = 0;
    for (int i = 0; i < right->suffix_count; ++i) {
        append_group(out->suffix_gcd, out->suffix_len, &out->suffix_count,
                     right->suffix_gcd[i], right->suffix_len[i]);
    }
    for (int i = 0; i < left->suffix_count; ++i) {
        append_group(out->suffix_gcd, out->suffix_len, &out->suffix_count,
                     gcd_int(right->gcd_all, left->suffix_gcd[i]),
                     left->suffix_len[i]);
    }
}

static void make_leaf(Node *node, int value) {
    node->len = 1;
    node->gcd_all = value;
    node->answer = value > 1 ? 1 : 0;
    node->prefix_count = node->suffix_count = 1;
    node->prefix_gcd[0] = node->suffix_gcd[0] = value;
    node->prefix_len[0] = node->suffix_len[0] = 1;
}

static void build(int index, int left, int right) {
    if (left == right) {
        make_leaf(&tree[index], values[left]);
        return;
    }

    int mid = (left + right) / 2;
    build(index * 2, left, mid);
    build(index * 2 + 1, mid + 1, right);
    merge_nodes(&tree[index * 2], &tree[index * 2 + 1], &tree[index]);
}

static void update(int index, int left, int right, int position, int value) {
    if (left == right) {
        make_leaf(&tree[index], value);
        return;
    }

    int mid = (left + right) / 2;
    if (position <= mid)
        update(index * 2, left, mid, position, value);
    else
        update(index * 2 + 1, mid + 1, right, position, value);

    merge_nodes(&tree[index * 2], &tree[index * 2 + 1], &tree[index]);
}

static void query(int index, int left, int right, int ql, int qr, Node *out) {
    if (ql <= left && right <= qr) {
        *out = tree[index];
        return;
    }

    int mid = (left + right) / 2;
    if (qr <= mid) {
        query(index * 2, left, mid, ql, qr, out);
    } else if (ql > mid) {
        query(index * 2 + 1, mid + 1, right, ql, qr, out);
    } else {
        Node a, b;
        query(index * 2, left, mid, ql, qr, &a);
        query(index * 2 + 1, mid + 1, right, ql, qr, &b);
        merge_nodes(&a, &b, out);
    }
}

static int read_int(void) {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();

    int value = 0;
    while (c >= '0' && c <= '9') {
        value = value * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return value;
}

int main(void) {
    int n = read_int();
    int m = read_int();

    for (int i = 1; i <= n; ++i)
        values[i] = read_int();

    tree = (Node *)malloc((size_t)(4 * n + 5) * sizeof(Node));
    if (!tree) return 0;

    build(1, 1, n);

    for (int i = 0; i < m; ++i) {
        int type = read_int();
        int x = read_int();
        int y = read_int();

        if (type == 1) {
            values[x] = y;
            update(1, 1, n, x, y);
        } else {
            Node result;
            query(1, 1, n, x, y, &result);
            printf("%lld\n", result.answer);
        }
    }

    free(tree);
    return 0;
}
